const SM = { role: "System Manager", read: 1 as const, write: 1 as const, create: 1 as const, delete: 1 as const, report: 1 as const, export: 1 as const };
const rw = (role: string) => ({ role, read: 1 as const, write: 1 as const, create: 1 as const, report: 1 as const, export: 1 as const });
const ro = (role: string) => ({ role, read: 1 as const, report: 1 as const });
type F = PluginDocType["fields"][number];
const f = (fieldname: string, label: string, fieldtype: string, extra: Partial<F> = {}): F => ({ fieldname, label, fieldtype, ...extra } as F);
const L = (fieldname: string, label: string, options: string, extra: Partial<F> = {}) => f(fieldname, label, "Link", { options, ...extra });
const S = (fieldname: string, label: string, options: string[], extra: Partial<F> = {}) => f(fieldname, label, "Select", { options: options.join("\n"), ...extra });
const listed = { in_list_view: 1, in_standard_filter: 1 } as Partial<F>;
