/** The always-active shared Core manifest (overlaid first by src/plugins/runtime.ts; never listed as an installable app). */
export const CORE_MANIFEST: PluginManifest = {
  name: CORE_APP, title: "DIGIT Core", title_ar: "نواة ديجيت", version: "1.0.0", publisher: "Digit", email: "dev@example.com", license: "MIT",
  description: "Shared Core DocTypes every DIGIT app points to.", description_ar: "أنواع المستندات المشتركة في النواة التي تستخدمها كل تطبيقات ديجيت.",
  host_app: "erpnext", module: CORE_MODULE, required_apps: ["frappe", "erpnext"],
  doctypes: CORE_DOCTYPES, custom_fields: CORE_CUSTOM_FIELDS, translations: CORE_TRANSLATIONS,
};
/** Route slug of a Core DocType (prefixed so it never collides with an app DocType of a similar name). */
export const coreSlug = (name: string) => `core_${name.toLowerCase().replace(/[^a-z0-9]+/g, "_")}`;
export const isCoreDocType = (name: string) => CORE_DOCTYPES.some((d) => d.name === name);
